print(npm_df['Ordinal'].describe())

# Extract slug and stars from Project_Information
slug_re = re.compile(r'The project ([\w\-\._/]+) (?:is hosted on GitHub|on GitHub)')
star_re = re.compile(r'([0-9][0-9,]*)\s+stars', re.IGNORECASE)
star_re2 = re.compile(r'stars count of\s+([0-9][0-9,]*)', re.IGNORECASE)

def extract_slug(txt):
    m = slug_re.search(txt)
    return m.group(1) if m else None

def extract_stars(txt):
    m = star_re.search(txt)
    if m:
        return int(m.group(1).replace(',',''))
    m = star_re2.search(txt)
    if m:
        return int(m.group(1).replace(',',''))
    return None

pi['slug'] = pi['Project_Information'].apply(extract_slug)
pi['stars'] = pi['Project_Information'].apply(extract_stars)
