print("stars nulls:", pi['stars'].isna().sum(), "/", len(pi))
print(pi.head())

# Add more patterns
slug_patterns += [
    re.compile(r'on GitHub,?\s+named ([\w\-\._/]+)', re.IGNORECASE),
    re.compile(r'is named ([\w\-\._/]+)', re.IGNORECASE),
    re.compile(r'titled ([\w\-\._/]+) is hosted', re.IGNORECASE),
    re.compile(r'under the repository ([\w\-\._/]+)', re.IGNORECASE),
]

def extract_slug3(txt):
    # Try to find any owner/repo style token first by looking for first '/' word
    for p in slug_patterns:
        m = p.search(txt)
        if m:
            s = m.group(1)
            if '/' in s:
                return s
    # Fallback: find first word containing exactly one slash
    m = re.search(r'\b([\w\-\.]+/[\w\-\.]+)\b', txt)
    if m:
        return m.group(1)
    return None

pi['slug'] = pi['Project_Information'].apply(extract_slug3)
